CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS characters (id INTEGER PRIMARY KEY, name TEXT NOT NULL UNIQUE, position TEXT NOT NULL, price INTEGER NOT NULL, color TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS students (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, login TEXT NOT NULL UNIQUE, pin_hash TEXT NOT NULL, character_id INTEGER NOT NULL REFERENCES characters(id));
CREATE TABLE IF NOT EXISTS clubs (id INTEGER PRIMARY KEY AUTOINCREMENT, student_id INTEGER NOT NULL UNIQUE REFERENCES students(id), name TEXT NOT NULL, balance INTEGER NOT NULL DEFAULT 100, crest TEXT NOT NULL DEFAULT '⚡');
CREATE TABLE IF NOT EXISTS roster (club_id INTEGER NOT NULL REFERENCES clubs(id), character_id INTEGER NOT NULL REFERENCES characters(id), PRIMARY KEY(club_id,character_id));
CREATE TABLE IF NOT EXISTS character_scores (season INTEGER NOT NULL, week INTEGER NOT NULL, character_id INTEGER NOT NULL, points INTEGER NOT NULL, PRIMARY KEY(season,week,character_id));
CREATE TABLE IF NOT EXISTS club_scores (season INTEGER NOT NULL, week INTEGER NOT NULL, club_id INTEGER NOT NULL, points INTEGER NOT NULL, bonus INTEGER NOT NULL, PRIMARY KEY(season,week,club_id));
CREATE TABLE IF NOT EXISTS mission_done (season INTEGER NOT NULL, week INTEGER NOT NULL, club_id INTEGER NOT NULL, mission_id INTEGER NOT NULL, PRIMARY KEY(season,week,club_id,mission_id));
CREATE TABLE IF NOT EXISTS transfers (id INTEGER PRIMARY KEY AUTOINCREMENT, season INTEGER NOT NULL, week INTEGER NOT NULL, club_id INTEGER NOT NULL, sold_id INTEGER NOT NULL, bought_id INTEGER NOT NULL, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
